{
  "$schema": "https://opencode.ai/config.json",
  "model": "grok/grok-4.6",
  "provider": {
    "grok": {
      "npm": "@ai-sdk/openai",
      "name": "Grok via Sub2API",
      "options": {
        "baseURL": "${endpoint}",
        "apiKey": "${apiKey}"
      },
      "models": {
        "grok-4.6": {
          "name": "Grok 4.6",
          "reasoning": true,
          "attachment": true,
          "limit": {
            "context": 500000,
            "output": 64000
          },
          "modalities": {
            "input": [
              "text",
              "image",
              "pdf"
            ],
            "output": [
              "text"
            ]
          },
          "options": {
            "reasoningEffort": "xhigh"
          },
          "variants": {
            "xhigh": {
              "reasoningEffort": "xhigh"
            }
          }
        },
        "grok-4.5": {
          "name": "Grok 4.5",
          "reasoning": true,
          "attachment": true,
          "limit": {
            "context": 500000,
            "output": 64000
          },
          "modalities": {
            "input": [
              "text",
              "image",
              "pdf"
            ],
            "output": [
              "text"
            ]
          }
        }
      }
    }
  }
}

params.usageScript:
({
  request: {
    url: "${baseUrl}/v1/usage",
    method: "GET",
    headers: { "Authorization": "Bearer ${apiKey}" }
  },
  extractor: function(response) {
    const remaining = response?.remaining ?? response?.quota?.remaining ?? response?.balance;
    const unit = response?.unit ?? response?.quota?.unit ?? "USD";
    return {
      isValid: response?.is_active ?? response?.isValid ?? true,
      remaining,
      unit
    };
  }
})
